INSERT INTO `announcements` VALUES (5,'Welcome Back to School!','Welcome Back to School!','Welcome Back to School!','We are excited to welcome all students back for the new academic year. Please check the school calendar for important dates.','We are excited to welcome all students back for the new academic year. Please check the school calendar for important dates.','We are excited to welcome all students back for the new academic year. Please check the school calendar for important dates.',NULL,'all',NULL,NULL,1,'published','2026-09-11 13:02:53','2026-09-11 19:48:15','announcement','medium','Admin User','[\"students\",\"parents\",\"teachers\",\"all\"]','data:image/jpeg;base64,',NULL,'image',0,0,0,'2026-09-11','15:02'),(6,'Parent-Teacher Meeting','Parent-Teacher Meeting','Parent-Teacher Meeting','We invite all parents to attend the upcoming parent-teacher meeting on Saturday, September 15, 2026 at 3:00 PM.','We invite all parents to attend the upcoming parent-teacher meeting on Saturday, September 15, 2026 at 3:00 PM.','We invite all parents to attend the upcoming parent-teacher meeting on Saturday, September 15, 2026 at 3:00 PM.',NULL,'all',NULL,NULL,1,'published','2026-09-14 21:15:55','2026-09-14 21:15:55','announcement','medium','Admin User','[\"students\",\"parents\",\"teachers\",\"all\"]','data:image/jpeg;base64,',NULL,'image',0,0,0,'2026-09-14','23:15'),(7,'Exam Schedule Released','Exam Schedule Released','Exam Schedule Released','The final exam schedule for the current semester has been released. Please check your child\'s class schedule for specific timings.','The final exam schedule for the current semester has been released. Please check your child\'s class schedule for specific timings.','The final exam schedule for the current semester has been released. Please check your child\'s class schedule for specific timings.',NULL,'all',NULL,NULL,1,'published','2026-09-16 05:02:17','2026-09-16 05:02:17','exam','medium','Admin User','[\"students\",\"parents\",\"teachers\",\"all\"]','data:image/png;base64,',NULL,'image',0,0,0,'2026-09-16','07:01'),(8,'Quran Memorization Competition','Quran Memorization Competition','Quran Memorization Competition','The annual Quran Memorization Competition will be held on May 15, 2026. All students are encouraged to participate.','The annual Quran Memorization Competition will be held on May 15, 2026. All students are encouraged to participate.','The annual Quran Memorization Competition will be held on May 15, 2026. All students are encouraged to participate.',NULL,'all',NULL,NULL,1,'published','2026-09-20 11:26:24','2026-09-20 11:26:24','announcement','medium','Admin User','[\"students\",\"parents\",\"teachers\",\"all\"]','data:image/jpeg;base64,',NULL,'image',0,0,0,'2026-09-20','12:25'),(9,'Annual Sports Day','Annual Sports Day',NULL,'Join us for our Annual Sports Day celebration on Friday, October 20, 2026. Parents and families are warmly invited to attend.','Join us for our Annual Sports Day celebration on Friday, October 20, 2026. Parents and families are warmly invited to attend.',NULL,NULL,'all',NULL,NULL,1,'published','2026-09-20 14:08:56','2026-09-20 14:08:56','announcement','medium','Admin User','[\"students\",\"parents\",\"teachers\",\"all\"]','data:image/jpeg;base64,',NULL,'image',0,0,0,'2026-09-20','15:08');
